ALTER TABLE users ADD COLUMN edit_version INT NOT NULL DEFAULT 1, ADD COLUMN last_successful_login_at DATETIME(6) NULL, ADD CONSTRAINT ck_users_edit_version CHECK(edit_version>0);
ALTER TABLE categories ADD COLUMN edit_version INT NOT NULL DEFAULT 1, ADD CONSTRAINT ck_categories_edit_version CHECK(edit_version>0);
ALTER TABLE suppliers ADD COLUMN edit_version INT NOT NULL DEFAULT 1, ADD CONSTRAINT ck_suppliers_edit_version CHECK(edit_version>0);
ALTER TABLE transactions ADD COLUMN reason_code VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN reference_number VARCHAR(100) NULL, ADD COLUMN party_text VARCHAR(150) NULL, ADD COLUMN movement_kind VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD CONSTRAINT ck_movement_kind CHECK(movement_kind IS NULL OR movement_kind IN ('ordinary','opening','reversal','adjustment')), ADD CONSTRAINT ck_movement_reason CHECK(reason_code IS NULL OR (type='IN' AND reason_code IN ('purchase_receipt','customer_return','other_receipt')) OR (type='OUT' AND reason_code IN ('sale_release','supplier_return','damage_writeoff','internal_use','other_release')));
CREATE INDEX idx_transactions_reason_date ON transactions(reason_code,transaction_date,transaction_id);
